class LogFormatter(logging.Formatter):
    def __init__(self):
        super(LogFormatter, self).__init__(
            fmt="%(color)s%(levelname)1.1s%(end_color)s %(message)s",
            datefmt="%Y-%m-%d %H:%M:%S"
        )

    def format(self, record):
        record.message = record.getMessage()
        if self.usesTime():
            record.asctime = self.formatTime(record, self.datefmt)
        if hasattr(record, "color") and record.color:
            # If the record has a color attribute, use it.
            color = record.color
        elif record.levelno >= logging.ERROR:
            color = logging._STYLES['%'].style._STYLES['red'][1]
        elif record.levelno >= logging.WARNING:
            color = logging._STYLES['%'].style._STYLES['yellow'][1]
        else:
            color = logging._STYLES['%'].style._STYLES['reset'][1]
        record.color = color
        record.end_color = logging._STYLES['%'].style._STYLES['reset'][1]
        return logging.Formatter.format(self, record)

def define_logging_options():
    options.define("log_to_stderr", default=True, help="Log to stderr", type=bool)
    options.define("log_file_prefix", default="", help="Log file prefix", type=str)
    options.define("log_rotate_mode", default="time", help="Log rotate mode", type=str)
