class OptionParser(object):
    def __init__(self):
        self.options = {}

    def define(self, name, default=None, help=None, type=None):
        self.options[name] = {
            'default': default,
            'help': help,
            'type': type,
            'value': default
        }

    def parse_command_line(self, args=None):
        import sys
        import optparse
        parser = optparse.OptionParser()
        for name, info in self.options.items():
            parser.add_option("--" + name, help=info['help'], type=info['type'], default=info['default'])
        (options, args) = parser.parse_args(args or sys.argv[1:])
        for name, value in options.__dict__.items():
            self.options[name]['value'] = value

    @property
    def log_to_stderr(self):
        return self.options['log_to_stderr']['value']

    @property
    def log_file_prefix(self):
        return self.options['log_file_prefix']['value']

    def enable_pretty_logging(self):
        logger = logging.getLogger()
        logger.setLevel(logging.DEBUG)
        if self.log_to_stderr:
            logger.addHandler(_stderr_handler())
        if self.log_file_prefix:
